class Solution:
    def solve(self, head):
        if not head:
            return head

        even_head = None
        odd_head = None
        even_tail = None
        odd_tail = None

        current = head

        while current:
            if current.val % 2 == 0:
                if not even_head:
                    even_head = current
                    even_tail = even_head
                else:
                    even_tail.next = current
                    even_tail = current
            else:
                if not odd_head:
                    odd_head = current
                    odd_tail = odd_head
                else:
                    odd_tail.next = current
                    odd_tail = current
            current = current.next

        if even_tail:
            even_tail.next = odd_head
        if odd_tail:
            odd_tail.next = None

        if even_head:
            return even_head
        else:
            return odd_head
